record.official_checksum_match = record.local_zip_sha256 === record.official_sha256;
record.checksum_verified_at = new Date().toISOString();
if (!record.official_checksum_match) throw new Error("官方CHECKSUM与本地SHA-256不一致");

const listing = await run("unzip", ["-Z1", zipPath]);
if (listing.code !== 0) throw new Error(`ZIP目录读取失败: ${listing.stderr}`);
record.zip_entries = listing.stdout.split("\n").filter(Boolean);
const test = await run("unzip", ["-t", zipPath]);
record.zip_structure_ok = test.code === 0 && record.zip_entries.length > 0;
