async function sha256(filePath) {
  return await new Promise((resolve, reject) => {
    const hash = crypto.createHash("sha256");
    const stream = fs.createReadStream(filePath);
    stream.on("data", (chunk) => hash.update(chunk));
    stream.on("error", reject);
    stream.on("end", () => resolve(hash.digest("hex")));
  });

async function extractEntry(zipPath, entryName, outputPath) {
  const partPath = `${outputPath}.part`;
  await fsp.rm(partPath, { force: true });
  const output = fs.createWriteStream(partPath, { flags: "wx" });
  const child = spawn("unzip", ["-p", zipPath, entryName], { stdio: ["ignore", "pipe", "pipe"] });
  const errors = [];
  child.stderr.on("data", (chunk) => errors.push(chunk));
  const codePromise = new Promise((resolve, reject) => {
    child.on("error", reject);
    child.on("close", resolve);
  });
  try {
    await pipeline(child.stdout, output);
    const code = await codePromise;
    if (code !== 0) throw new Error(`unzip -p失败: ${Buffer.concat(errors).toString("utf8")}`);
    await fsp.rename(partPath, outputPath);

const zipStat = await fsp.stat(zipPath);
record.zip_size = zipStat.size;
record.local_zip_sha256 = await sha256(zipPath);
record.official_checksum_match = record.local_zip_sha256 === record.official_sha256;
record.checksum_verified_at = new Date().toISOString();
if (!record.official_checksum_match) throw new Error("官方CHECKSUM与本地SHA-256不一致");

const listing = await run("unzip", ["-Z1", zipPath]);
if (listing.code !== 0) throw new Error(`ZIP目录读取失败: ${listing.stderr}`);
