def prepare_artifact_builder() -> None:
    builder = BASE_BUILDER.read_text(encoding="utf-8")
    builder = builder.replace("阶段05", "阶段06")
    builder = builder.replace("S05T", "S06T")
    builder = builder.replace(
        'const sheet = workbook.worksheets.add(sheetName);\n  if (normalizedRows.length) {',
        '''const sheet = workbook.worksheets.add(sheetName);
  normalizedColumns.forEach((column, index) => {
    const excelColumn = excelColumnName(index + 1);
    sheet.getRange(`${excelColumn}1:${excelColumn}${Math.max(normalizedRows.length + 8, 12)}`).setNumberFormat("@");
  });
  if (normalizedRows.length) {''',
    )
    builder = builder.replace(
        'const sheet = workbook.worksheets.add(sheetName);\n  const recordCount = await writeJsonl(sheet, dataset.data_jsonl, columns);',
        '''const sheet = workbook.worksheets.add(sheetName);
  columns.forEach((column, index) => {
    const excelColumn = excelColumnName(index + 1);
    sheet.getRange(`${excelColumn}1:${excelColumn}${Math.max(dataset.expected_record_count + 8, 12)}`).setNumberFormat("@");
  });
  const recordCount = await writeJsonl(sheet, dataset.data_jsonl, columns);''',
    )
    TEMP_BUILDER.write_text(builder, encoding="utf-8")

