def stage_minutes(stage: dict) -> list[int]:
    start = int(stage["阶段开始毫秒"])
    end = int(stage["阶段结束毫秒（不含）"])
    first = (start // 60000) * 60000
    last = ((end - 1) // 60000) * 60000
    return list(range(first, last + 60000, 60000))


def build_market_need_maps(stages: list[dict]) -> dict:
    needed = defaultdict(set)
    boundary = defaultdict(set)
    boundary_stage_refs = defaultdict(list)
    stage_by_id = {x["stage_id"]: x for x in stages}
    for stage in stages:
        symbol = stage["symbol"]
        for minute in stage_minutes(stage):
            date = dt.datetime.fromtimestamp(minute / 1000, dt.timezone.utc).date().isoformat()
            needed[(symbol, date)].add(minute)
        start_boundary = int(stage["开始边界分钟"])
        end_boundary = int(stage["结束边界分钟"])
        for minute in {start_boundary, end_boundary}:
            date = dt.datetime.fromtimestamp(minute / 1000, dt.timezone.utc).date().isoformat()
            boundary[(symbol, date)].add(minute)
            boundary_stage_refs[(symbol, minute)].append(stage["stage_id"])
    return {
        "needed": needed,
        "boundary": boundary,
        "boundary_stage_refs": boundary_stage_refs,
        "stage_by_id": stage_by_id,
    }

