async function consume(worker, workerIndex) {
  while (true) {
    const index = nextIndex++;
    if (index >= imagePaths.length) return;
    const imagePath = imagePaths[index];
    const { data } = await worker.recognize(
      imagePath,
      { rectangle: { left: 500, top: 1080, width: 2850, height: 900 } },
      { text: true, tsv: true },
    );
    const words = (data.tsv || "")
      .split(/\r?\n/)
      .slice(1)
      .map((line) => line.split("\t"))
      .filter((parts) => parts[0] === "5" && parts.length >= 12)
      .map((parts) => ({
        left: Number(parts[6]),
        top: Number(parts[7]),
        width: Number(parts[8]),
        height: Number(parts[9]),
        confidence: Number(parts[10]),
        text: parts.slice(11).join("\t"),
      }));
    results.push({
      file_name: path.basename(imagePath),
      file_path: imagePath,
      ocr_confidence: Number(data.confidence),
      crop: { left: 500, top: 1080, width: 2850, height: 900 },
      text: data.text || "",
      words,
    });

await Promise.all(workers.map((worker, index) => consume(worker, index)));
