const [, , configPath, outputPath] = process.argv;
const config = JSON.parse(await fs.readFile(configPath, "utf8"));
const result = [];
for (const item of config) {
  const workbook = await SpreadsheetFile.importXlsx(await FileBlob.load(item.path));
  const sheets = [];
  for (const sheetConfig of item.sheets) {
    const sheetName = typeof sheetConfig === "string" ? sheetConfig : sheetConfig.name;
    const sheet = workbook.worksheets.getItem(sheetName);
    const used =
      typeof sheetConfig === "string" || !sheetConfig.range
        ? sheet.getUsedRange(true)
        : sheet.getRange(sheetConfig.range);
    sheets.push({
      name: sheetName,
      address: used.address,
      values: used.values,
      formulas: item.includeFormulas ? used.formulas : undefined,
    });
  }
  result.push({ path: path.resolve(item.path), sheets });
}
await fs.writeFile(outputPath, JSON.stringify(result));

