const onlyTokens = onlyArg ? onlyArg.slice(7).split(",").filter(Boolean) : [];
const inheritOnly = args.includes("--inherit-only");
const selected = (itemPath) => !onlyTokens.length || onlyTokens.some((token) => itemPath.includes(token));
