  const wb = Workbook.create();
  const placeholders = spec.sheets.map((s) => wb.worksheets.add(s.name));
  const built = spec.sheets.map((s, si) => writeSheet(wb, spec.path, s, si, placeholders[si]));
  const result = await qaAndPreview(wb, spec.path, built);
  await fs.mkdir(path.dirname(spec.path), { recursive: true });
  const output = await SpreadsheetFile.exportXlsx(wb); await output.save(spec.path);
  qa.workbooks.push({ path: spec.path, sheets: spec.sheets.map((s) => s.name), ...result });
  process.stdout.write(`[${wi + 1}/${workbookSpecs.length}] ${spec.path}\n`);
}

const inheritSpecs = (payload.inherit_workbooks || []).filter((spec) => selected(spec.path));
for (let ii = 0; ii < inheritSpecs.length; ii += 1) {
  const spec = inheritSpecs[ii];
  const blob = await FileBlob.load(spec.source);
  const wb = await SpreadsheetFile.importXlsx(blob);
  const note = writeSheet(wb, spec.path, spec.note_sheet, 99);
  const sheetInfo = await wb.inspect({ kind: "sheet", include: "id,name", maxChars: 10000 });
  const errorScan = await wb.inspect({ kind: "match", searchTerm: "#REF!|#DIV/0!|#VALUE!|#NAME\\?|#N/A", options: { useRegex: true, maxResults: 300 }, summary: "M1 inherited workbook formula scan", maxChars: 10000 });
  const inheritedPreviews = [];
  for (const line of sheetInfo.ndjson.split("\n").filter(Boolean)) {
    const item = JSON.parse(line);
    if (item.kind !== "sheet") continue;
    const match = String(item.range || "A1:A24").match(/^([A-Z]+)(\d+):([A-Z]+)(\d+)$/);
    const renderRange = match ? `A1:${match[3]}${Math.min(Number(match[4]),24)}` : "A1:L24";
    const previewBlob = await wb.render({ sheetName: item.name, range: renderRange, scale: 1, format: "png" });
    const previewPath = path.join(previewDir, `${safeName(path.basename(spec.path))}__${safeName(item.name)}.png`);
    await fs.writeFile(previewPath, new Uint8Array(await previewBlob.arrayBuffer()));
    inheritedPreviews.push(previewPath);
  }
  await fs.mkdir(path.dirname(spec.path), { recursive: true });
  const output = await SpreadsheetFile.exportXlsx(wb); await output.save(spec.path);
  qa.workbooks.push({ path: spec.path, inherited_from: spec.source, sheets: sheetInfo.ndjson, errors: errorScan.ndjson, previews: inheritedPreviews });
  process.stdout.write(`[inherit ${ii + 1}/${inheritSpecs.length}] ${spec.path}\n`);

