function interfaceMatrix(contract, schema) {
  const headers = ["section", "item", "attribute", "value", "status"];
  const rows = [];
  for (const [key, value] of Object.entries(contract)) {
    if (Array.isArray(value)) continue;
    rows.push({ section: "READ_CONTRACT", item: key, attribute: "value", value: String(value), status: "FROZEN" });
  }
  for (const allowed of contract.allowed_files) {
    rows.push({ section: "ALLOWED_FILE", item: path.basename(allowed), attribute: "exact_path", value: allowed, status: "READ_ONLY" });
  }
  for (const [dataset, info] of Object.entries(schema.datasets)) {
    for (const field of info.fields) {
      rows.push({
        section: "FIELD_SCHEMA",
        item: dataset,
        attribute: field.name,
        value: `${field.type}; nullable=${String(field.nullable)}`,
        status: "ALLOWED_FIELD",
      });
    }
  }
  return matrixFromObjects(headers, rows);

