def candidate_tu(event_time: datetime, cycles: list[dict]) -> str:
    overlapping = []
    for row in cycles:
        if row["_start"] and row["_end"] and row["_start"] <= event_time <= row["_end"]:
            overlapping.extend(row["_ids"])
    if overlapping:
        return "｜".join(sorted(set(overlapping)))
    future = [
        row for row in cycles
        if row["_start"] and event_time < row["_start"] <= event_time + timedelta(hours=24) and row["_ids"]
    ]
    if future:
        next_time = min(row["_start"] for row in future)
        ids = [i for row in future if row["_start"] == next_time for i in row["_ids"]]
        return "可能关联后续" + "｜".join(sorted(set(ids)))

