const base = "人工复盘增强版_修正工程/R1_10笔成品原型/技术中间结果";
const targets = [
  ["06C_T067首仓前资金修正.csv", "T067修正", 11],
  ["06C_首仓与逐次加仓阶梯.csv", "仓位阶梯", 25],
  ["06C_限价减仓平仓尝试明细.csv", "限价明细", 41],
  ["06C_逐笔平仓意图汇总.csv", "平仓汇总", 11],
  ["06C_资金用户展示结果.csv", "资金展示", 11],
  ["06C_主动交易用户汇总.csv", "主动交易汇总", 11],
  ["06C_用户枚举中文映射.csv", "枚举映射", 25],
];

const results = [];
for (const [file, sheetName, expectedRows] of targets) {
  const csvText = await fs.readFile(`${base}/${file}`, "utf8");
  const workbook = await Workbook.fromCSV(csvText, { sheetName });

const table = await workbook.inspect({
  kind: "table",
  range: `${sheetName}!A1:AZ${Math.min(expectedRows, 8)}`,
  include: "values,formulas",
  tableMaxRows: Math.min(expectedRows, 8),
  tableMaxCols: 52,
  tableMaxCellChars: 120,
  maxChars: 12000,
});
const formulaErrors = await workbook.inspect({
  kind: "match",
  searchTerm: "#REF!|#DIV/0!|#VALUE!|#NAME\\?|#N/A",
  options: { useRegex: true, maxResults: 50 },
  summary: `${file}公式错误扫描`,
});
results.push({
  file,
  parsed: true,
  expectedRows,
  tablePreview: table.ndjson,
  formulaErrorScan: formulaErrors.ndjson,
});

  if (file === "06C_主动交易用户汇总.csv") {
    const sheet = workbook.worksheets.getItem(sheetName);
    sheet.getRange("A:A").format.columnWidth = 12;
    sheet.getRange("B:B").format.columnWidth = 14;
    sheet.getRange("C:C").format.columnWidth = 14;
    sheet.getRange("D:D").format.columnWidth = 10;
    sheet.getRange("E:F").format.columnWidth = 24;
    sheet.getRange("G:H").format.columnWidth = 14;
    sheet.getRange("A1:H6").format.wrapText = false;
    const preview = await workbook.render({
      sheetName,
      range: "A1:H6",
      scale: 1.5,
      format: "png",
    });
    await fs.writeFile("/tmp/06c_active_summary_preview.png", new Uint8Array(await preview.arrayBuffer()));
  }
}

for (const result of results) {
  console.log(JSON.stringify({ file: result.file, parsed: result.parsed, expectedRows: result.expectedRows }));
  console.log(result.tablePreview);
  console.log(result.formulaErrorScan);
}

